<template>
  <div class="analitic-container">
    <h2>Dudina</h2>
  </div>
</template>

<script>
export default {
  name: "AnaliticComponent",
  components: {},
  data() {
    return {
      roleName: '',
    }
  },
  methods: {
    getRoleName() {
      this.roleName = JSON.parse(localStorage.getItem('sale-auth')).role;
    },
    isLoadedPage(){
      localStorage.setItem('checkLoadStatus', 'loaded');
    }
  },
  mounted() {
    this.isLoadedPage();
    this.getRoleName();
  },
  beforeUnmount() {}
}
</script>

